-- 세트 46: kubectl 명령과 YAML 해부하기
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md): 이해 없이 복사하지 않도록 명령·YAML 을 읽는 연습. 정답·해설은 서버만 안다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template) VALUES
  (46, 1, 'kubectl 명령의 구조 읽기', '`kubectl get pods -n dev -o wide` 를 조각으로 나누면 어떻게 읽을까요?', 'kubectl 은 `동사 자원 이름 옵션` 순서로 읽습니다. `-n` 은 어느 구역(네임스페이스)에서인지, `-o` 는 어떤 형식으로 보여 줄지입니다.', NULL, NULL, '[]', 'choice', '["동사 `get`, 자원 `pods`, 네임스페이스 `dev`, 출력 형식 `wide`(자세히)", "동사 `pods`, 자원 `get`, 네임스페이스 `wide`, 출력 형식 `dev`", "동사 `kubectl`, 자원 `get`, 이름 `pods`", "전부 옵션이다"]', 0, '`kubectl <동사> <자원> [이름] [옵션]` 구조입니다. `get`(조회) `pods`(Pod 들) `-n dev`(dev 네임스페이스에서) `-o wide`(IP·노드까지 자세히)로 읽습니다. 동사를 `delete`, `describe`, `logs` 등으로 바꾸면 같은 구조로 다른 일을 합니다.', NULL, NULL),
  (46, 2, 'kubectl 명령 빈칸 채우기: dev 의 Pod 목록', '`dev` 네임스페이스에 있는 **Pod 목록을 조회**하려고 합니다. 명령의 빈칸을 채우세요.', '조회하는 동사와 네임스페이스 이름이 필요합니다. 지우는 동사(`delete`)와 헷갈리지 마세요.', NULL, NULL, '[]', 'fill', '["get", "delete", "dev", "logs", "wide"]', NULL, '`get` 은 조회, `-n` 은 네임스페이스를 지정합니다. `-n dev` 를 빼면 현재 기본 네임스페이스(보통 `default`)를 봅니다. `delete` 는 지우는 동사라서, 복사한 명령에서 동사가 `delete` 인지 `get` 인지를 가장 먼저 확인하세요.', '[0, 2]', 'kubectl {0} pods -n {1}'),
  (46, 3, 'Deployment YAML 의 최상위 항목 순서대로 놓기', 'Deployment 를 만드는 YAML 파일의 **최상위 항목**이 섞여 있습니다. 일반적으로 쓰는 순서대로 놓으세요.', '"무슨 버전의 API 로, 어떤 종류를, 이름과 라벨은, 원하는 상태는"이라고 읽으면 순서가 보입니다.', NULL, NULL, '[]', 'order', '["`spec:` (원하는 상태: 개수, 컨테이너 등)", "`kind: Deployment` (자원의 종류)", "`apiVersion: apps/v1` (사용할 API 버전)", "`metadata:` (이름, 라벨 같은 식별 정보)"]', NULL, '쿠버네티스 YAML 은 거의 모두 `apiVersion` → `kind` → `metadata` → `spec` 입니다. 무슨 API 로(`apiVersion`) 어떤 종류(`kind`)를 어떤 이름으로(`metadata`) 어떤 상태로(`spec`) 만들지 순서대로 적습니다.', '[2, 1, 3, 0]', NULL),
  (46, 4, 'YAML 들여쓰기의 의미 알기', 'YAML 에서 줄 앞의 **들여쓰기(공백)** 는 무슨 의미일까요?', 'YAML 은 괄호가 아니라 들여쓰기로 "안에 들어 있다"를 표현합니다. 탭 문자는 쓰지 않습니다.', NULL, NULL, '[]', 'choice', '["보기 좋게 하려는 장식이라 의미가 없다", "위아래 항목의 포함 관계(어디 안에 속하는지)를 나타내서, 어긋나면 의미가 달라지거나 오류가 난다", "들여쓴 줄은 주석으로 처리된다", "들여쓴 줄은 무시된다"]', 1, 'YAML 의 들여쓰기는 **계층(포함 관계)** 입니다. 같은 깊이는 같은 단계이고, 더 들여쓴 줄은 바로 위 항목의 하위입니다. 공백 수가 어긋나면 엉뚱한 곳에 속하거나 오류가 납니다. 탭 문자는 허용되지 않으니 공백(보통 2칸)을 쓰세요.', NULL, NULL),
  (46, 5, 'Pod 개수를 정하는 YAML 필드 찾기', 'Deployment YAML 에서 **Pod 를 몇 개 유지할지** 정하는 필드는 무엇이고 어디에 쓸까요?', 'Deployment 에게 "원하는 상태"를 알려 주는 부분 안에 있습니다.', NULL, NULL, '[]', 'choice', '["`metadata.replicas`", "`spec.replicas` (spec 아래에 `replicas: 3` 처럼 쓴다)", "`kind.replicas`", "`apiVersion.replicas`"]', 1, '원하는 Pod 개수는 `spec` 아래의 `replicas` 입니다. `metadata` 는 이름·라벨 같은 식별 정보이고, "몇 개를 원하는가"는 원하는 상태인 `spec` 에 속합니다. `kubectl scale --replicas=3` 도 같은 값을 바꿉니다.', NULL, NULL),
  (46, 6, 'Deployment YAML 의 kind 와 replicas 빈칸 채우기', '아래 YAML 로 이름이 `web` 인 **Deployment** 를 만들고 Pod 를 **3개** 유지하려고 합니다. 빈칸을 채우세요.', '`kind` 에는 자원의 종류를, `replicas` 에는 유지할 Pod 개수를 씁니다.', NULL, NULL, '[]', 'fill', '["Deployment", "Service", "Pod", "3", "80"]', NULL, '`apps/v1` 은 Deployment 가 속한 API 그룹/버전이라서 `kind` 는 `Deployment` 입니다. `replicas: 3` 은 Pod 를 3개 유지하라는 뜻입니다. `Service` 나 `Pod` 는 다른 종류(`v1`)이고, `80` 은 개수가 아니라 포트 번호처럼 쓰는 값입니다.', '[0, 3]', 'apiVersion: apps/v1
kind: {0}
metadata:
  name: web
spec:
  replicas: {1}'),
  (46, 7, 'Service 가 Pod 를 찾는 방법 알기', 'Deployment 의 Pod 템플릿에는 `labels: app: web` 이 있습니다. 이 Pod 들 앞에 Service 를 만들려면 Service 에 무엇이 필요할까요?', 'Service 는 **라벨**로 어떤 Pod 로 요청을 보낼지 고릅니다.', NULL, NULL, '[]', 'choice', '["Pod 이름을 하나씩 모두 적는다", "`selector: app: web` 처럼 Pod 의 라벨과 같은 값을 적는다", "아무것도 필요 없다. 자동으로 연결된다", "Deployment 의 이름을 `kind` 에 적는다"]', 1, 'Service 는 **셀렉터(selector)** 가 라벨이 일치하는 Pod 들을 찾아 요청을 나눠 줍니다. Service 의 `selector` 와 Pod 의 `labels` 가 **서로 맞아야** 연결됩니다. 접속이 안 될 때 가장 먼저 의심할 곳이 이 라벨·셀렉터 불일치입니다.', NULL, NULL),
  (46, 8, 'kubectl apply 와 create 의 차이 알기', '같은 YAML 파일에 대해 `kubectl create -f web.yaml` 과 `kubectl apply -f web.yaml` 을 **두 번 이상** 실행합니다. 차이는 무엇일까요?', '이미 같은 이름의 자원이 있을 때 어떻게 동작할지를 생각해 보세요.', NULL, NULL, '[]', 'choice', '["둘은 완전히 같다", "`create` 는 이미 있으면 오류가 나고, `apply` 는 없으면 만들고 있으면 파일의 내용대로 바꾼다", "`apply` 는 한 번만 실행할 수 있다", "`create` 는 지우는 명령이다"]', 1, '`create` 는 **새로 만들기**만 해서 이미 있으면 `AlreadyExists` 오류가 납니다. `apply` 는 없으면 만들고 **있으면 변경점만 반영**해서 같은 파일을 여러 번 실행해도 됩니다. 그래서 YAML 파일 기반 작업은 보통 `apply -f` 를 씁니다.', NULL, NULL),
  (46, 9, '--dry-run=client -o yaml 의 용도 알기', '`kubectl create deployment web --image=nginx --dry-run=client -o yaml` 은 무엇을 할까요?', '`--dry-run=client` 는 "실제로는 하지 말고 흉내만", `-o yaml` 은 "YAML 로 보여 줘"입니다.', NULL, NULL, '[]', 'choice', '["nginx Deployment 를 만들고 YAML 파일로 저장한다", "실제로 만들지 않고, 만들었다면 사용할 YAML 을 화면에 출력한다 (YAML 뼈대를 얻는 데 쓴다)", "nginx 를 삭제한다", "클러스터의 모든 Deployment 를 보여 준다"]', 1, '`--dry-run=client` 는 실제로 만들지 않고 흉내만 내고, `-o yaml` 은 그 결과를 YAML 로 출력합니다. YAML 을 처음부터 쓰기 어려울 때 이 명령으로 **뼈대를 얻어서** (`> web.yaml` 로 저장) 필요한 부분만 고치면 편합니다. 복사한 YAML 보다 자기가 만든 뼈대가 더 이해하기 쉽습니다.', NULL, NULL),
  (46, 10, 'delete --all 의 범위 알기', '`kubectl delete pods --all` 을 **네임스페이스 지정 없이** 실행하면 무엇이 지워질까요?', '`-n` 이 없으면 현재 사용 중인 기본 네임스페이스를 대상으로 합니다. `--all` 은 "전부"입니다.', NULL, NULL, '[]', 'choice', '["클러스터 전체의 모든 Pod", "현재 네임스페이스(보통 `default`)의 모든 Pod", "이름이 `all` 인 Pod 하나", "아무것도 지워지지 않는다"]', 1, '네임스페이스를 지정하지 않으면 **현재 네임스페이스**가 대상이라서, `--all` 은 그 안의 모든 Pod 를 지웁니다. (Deployment 가 관리하는 Pod 는 다시 만들어지지만, 직접 만든 Pod 는 사라집니다.) 지우는 명령은 실행 전에 `kubectl get pods -n <네임스페이스>` 로 대상을 먼저 확인하세요.', NULL, NULL),
  (46, 11, 'apiVersion 이 자원마다 다른 이유 알기', 'Pod 와 Service 의 `apiVersion` 은 `v1` 이고 Deployment 는 `apps/v1` 입니다. 이렇게 다른 이유로 알맞은 것은 무엇일까요?', '쿠버네티스 API 는 기능별로 **그룹**을 나눕니다. 가장 기본이 되는 자원은 그룹 이름이 없습니다.', NULL, NULL, '[]', 'choice', '["오타다. 모두 `v1` 로 써도 된다", "API 가 그룹으로 나뉘어 있어서, 기본(core) 자원(Pod, Service 등)은 `v1`, 워크로드(Deployment 등)는 `apps/v1` 처럼 그룹이 붙는다", "Deployment 는 오래된 버전이라 그렇다", "Service 는 사용하지 않는 버전이라 그렇다"]', 1, '쿠버네티스 API 는 그룹으로 나뉩니다. 기본(core) 자원인 Pod, Service, ConfigMap 등은 `v1`, Deployment·StatefulSet 같은 워크로드는 `apps/v1` 입니다. 새 자원의 `apiVersion` 이 헷갈리면 `kubectl api-resources` 나 `kubectl explain <자원>` 로 확인합니다.', NULL, NULL);
